/* Cookbook (2026-11-15): the recipes of the user's two books by Nicolas Aesthetics, "Cookbook 1.0" and "Cookbook 2.0",
   each recipe once. Read from the PDFs on the user's desktop with OCR; ingredients as printed, the steps rewritten
   short (Cookbook 1.0 explains them only on video, so its steps are this app's), the macros those printed for the
   whole recipe, checked against 4/4/9 kcal per gram. `est`: the page's numbers were unreadable, the macros are this
   app's estimate from the ingredients. Personal use: the app is the user's own and not indexed. */

export type CookCat = 'dejun' | 'pranz' | 'gustare' | 'desert';
export const COOK_CAT: Record<CookCat, string> = { dejun: 'Mic dejun', pranz: 'Prânz și cină', gustare: 'Gustări', desert: 'Dulciuri' };

export interface Recipe {
  id: string;
  name: string;
  cat: CookCat;
  book: '1.0' | '2.0';
  /** Whole recipe. */
  kcal: number; p: number; f: number; c: number;
  /** Pieces or portions the recipe makes (0 = one plate). */
  pieces: number;
  ing: string[];
  steps: string[];
  est?: boolean;
}

const R = (id: string, name: string, cat: CookCat, book: '1.0' | '2.0', kcal: number, p: number, f: number, c: number, pieces: number, ing: string[], steps: string[], est = false): Recipe =>
  ({ id, name, cat, book, kcal, p, f, c, pieces, ing, steps, ...(est ? { est } : {}) });

